async function createOpenSCAD() {
    return await OpenSCAD({
        noInitialRun: true,
        noExitRuntime: true,
        locateFile: path => "./modules/" + path
    });
}








async function compileOpenSCAD() {
    const code = scadInput.value;

    const inputFile = "/input.scad";
    const outputFile = "/output.stl";

    try {
        const scad = await createOpenSCAD();

        scad.FS.writeFile(inputFile, code);

        scad.callMain([
            inputFile,
            "-o",
            outputFile
        ]);

        const stlData = scad.FS.readFile(outputFile);

        const stlBuffer = stlData.buffer.slice(
            stlData.byteOffset,
            stlData.byteOffset + stlData.byteLength
        );

        currentSTLBuffer = stlBuffer;

        displaySTL(stlBuffer);

    } catch (err) {
        console.error("OpenSCAD error:", err);
        alert("OpenSCAD compile failed: " + err);
    }
}






