let currentSTLBuffer = null;
let currentMesh = null;
let isDragging = false;
let isPanning = false;
let previousMouse = { x: 0, y: 0 };

const scene = new THREE.Scene();

THREE.Object3D.DEFAULT_UP.set(0, 0, 1);

const grid = new THREE.GridHelper(400, 400);
grid.rotation.x = Math.PI / 2; // put grid on XY plane, Z is up
scene.add(grid);

const axes = new THREE.AxesHelper(10);
scene.add(axes);

const rect = canvas.parentElement.getBoundingClientRect();

const camera = new THREE.PerspectiveCamera(
    75,
    rect.width / rect.height,
    0.1,
    100000
);

const renderer = new THREE.WebGLRenderer({
    canvas,
    antialias: true
});

renderer.setSize(rect.width, rect.height);
renderer.setPixelRatio(window.devicePixelRatio || 1);

let cameraTarget = new THREE.Vector3(0, 0, 0);
let cameraDistance = 40;
let azimuth = -Math.PI / 3;
let elevation = Math.PI / 4;

function updateCamera() {
    elevation = Math.max(
        -Math.PI / 2 + 0.01,
        Math.min(Math.PI / 2 - 0.01, elevation)
    );
    camera.position.set(
        cameraTarget.x + cameraDistance * Math.cos(elevation) * Math.cos(azimuth),
        cameraTarget.y + cameraDistance * Math.cos(elevation) * Math.sin(azimuth),
        cameraTarget.z + cameraDistance * Math.sin(elevation)
    );

    camera.up.set(0, 0, 1);
    camera.lookAt(cameraTarget);
}

function animate() {
    requestAnimationFrame(animate);
    renderer.render(scene, camera);
}

updateCamera();
animate();

canvas.addEventListener("mousedown", e => {
    e.preventDefault();

    if (e.button === 0) isDragging = true;
    if (e.button === 1) isPanning = true;

    previousMouse.x = e.clientX;
    previousMouse.y = e.clientY;
});

window.addEventListener("mouseup", () => {
    isDragging = false;
    isPanning = false;
});

window.addEventListener("mousemove", e => {
    const dx = e.clientX - previousMouse.x;
    const dy = e.clientY - previousMouse.y;

    if (isDragging) {
        azimuth -= dx * 0.01;
        elevation += dy * 0.01;
        updateCamera();
    }

    if (isPanning) {
        const panSpeed = cameraDistance * 0.0015;

        const direction = new THREE.Vector3();
        camera.getWorldDirection(direction);

        const right = new THREE.Vector3()
            .crossVectors(direction, camera.up)
            .normalize();

        const up = new THREE.Vector3()
            .crossVectors(right, direction)
            .normalize();

        cameraTarget
            .addScaledVector(right, -dx * panSpeed)
            .addScaledVector(up, dy * panSpeed);

        updateCamera();
    }

    previousMouse.x = e.clientX;
    previousMouse.y = e.clientY;
});

canvas.addEventListener("wheel", e => {
    e.preventDefault();

    cameraDistance *= 1 + e.deltaY * 0.001;
    cameraDistance = Math.max(1, cameraDistance);

    updateCamera();
}, { passive: false });

canvas.addEventListener("auxclick", e => {
    if (e.button === 1) e.preventDefault();
});

canvas.addEventListener("contextmenu", e => e.preventDefault());

window.addEventListener("resize", () => {
    const rect = canvas.parentElement.getBoundingClientRect();

    camera.aspect = rect.width / rect.height;
    camera.updateProjectionMatrix();

    renderer.setSize(rect.width, rect.height);
});



function displaySTL(stlData) {
    const geometry = parseSTL(stlData);

    geometry.computeBoundingBox();
    geometry.computeBoundingSphere();

    if (currentMesh) {
        scene.remove(currentMesh);
        currentMesh.geometry.dispose();
        currentMesh.material.dispose();
    }

    currentMesh = new THREE.Mesh(
        geometry,
        new THREE.MeshNormalMaterial({ side: THREE.DoubleSide })
    );

    // Keep the model in its real OpenSCAD/STL position.
    // Do NOT centre it, otherwise the grid/origin becomes meaningless.
    currentMesh.position.set(0, 0, 0);
    currentMesh.rotation.set(0, 0, 0);

    scene.add(currentMesh);

    const box = new THREE.Box3().setFromObject(currentMesh);
    const center = new THREE.Vector3();
    const size = new THREE.Vector3();

    box.getCenter(center);
    box.getSize(size);

    cameraTarget.copy(center);

    const maxSize = Math.max(size.x, size.y, size.z);
    const fov = camera.fov * Math.PI / 180;

    //cameraDistance = Math.abs(maxSize / Math.sin(fov / 2)) * 1.8;

    if (!Number.isFinite(cameraDistance) || cameraDistance <= 0) {
        cameraDistance = 10;
    }

    camera.near = Math.max(cameraDistance / 1000, 0.01);
    camera.far = cameraDistance * 1000;
    camera.updateProjectionMatrix();

    // Starting angled view
    //azimuth = -Math.PI / 2;
    //elevation = Math.PI / 5;

    updateCamera();
}



function parseSTL(data) {

    const buffer =
        data instanceof ArrayBuffer
            ? data
            : data.buffer;

    const view = new DataView(buffer);

    // Detect binary STL
    const faceCount = view.getUint32(80, true);
    const expectedSize = 84 + faceCount * 50;

    const geometry = new THREE.BufferGeometry();

    // BINARY STL
    if (expectedSize === buffer.byteLength) {

        const vertices = new Float32Array(faceCount * 9);
        const normals = new Float32Array(faceCount * 9);

        let offset = 84;

        for (let face = 0; face < faceCount; face++) {

            const nx = view.getFloat32(offset, true);
            const ny = view.getFloat32(offset + 4, true);
            const nz = view.getFloat32(offset + 8, true);

            offset += 12;

            for (let i = 0; i < 3; i++) {

                const index = face * 9 + i * 3;

                vertices[index]     = view.getFloat32(offset, true);
                vertices[index + 1] = view.getFloat32(offset + 4, true);
                vertices[index + 2] = view.getFloat32(offset + 8, true);

                normals[index]     = nx;
                normals[index + 1] = ny;
                normals[index + 2] = nz;

                offset += 12;
            }

            offset += 2; // attribute byte count
        }

        geometry.setAttribute(
            "position",
            new THREE.BufferAttribute(vertices, 3)
        );

        geometry.setAttribute(
            "normal",
            new THREE.BufferAttribute(normals, 3)
        );

    } else {

        // ASCII STL
        const text = new TextDecoder().decode(buffer);

        const vertices = [];
        const normals = [];

        const faceRegex = /facet[\s\S]*?normal\s+([^\s]+)\s+([^\s]+)\s+([^\s]+)[\s\S]*?outer loop([\s\S]*?)endloop[\s\S]*?endfacet/g;

        let match;

        while ((match = faceRegex.exec(text)) !== null) {

            const nx = parseFloat(match[1]);
            const ny = parseFloat(match[2]);
            const nz = parseFloat(match[3]);

            const vertexRegex = /vertex\s+([^\s]+)\s+([^\s]+)\s+([^\s]+)/g;

            let vertexMatch;

            while ((vertexMatch = vertexRegex.exec(match[4])) !== null) {

                vertices.push(
                    parseFloat(vertexMatch[1]),
                    parseFloat(vertexMatch[2]),
                    parseFloat(vertexMatch[3])
                );

                normals.push(nx, ny, nz);
            }
        }

        geometry.setAttribute(
            "position",
            new THREE.Float32BufferAttribute(vertices, 3)
        );

        geometry.setAttribute(
            "normal",
            new THREE.Float32BufferAttribute(normals, 3)
        );
    }

    geometry.computeBoundingBox();
    geometry.computeBoundingSphere();

    return geometry;
}

