window.TOTP = {
    async generate(secret, options = {}) {
        const digits = options.digits ?? 6;
        const period = options.period ?? 30;

        const epoch = Math.floor(Date.now() / 1000);
        const counter = Math.floor(epoch / period);

        const key = base32ToBytes(secret);
        const msg = counterToBytes(counter);

        const cryptoKey = await crypto.subtle.importKey(
            "raw",
            key,
            { name: "HMAC", hash: "SHA-1" },
            false,
            ["sign"]
        );

        const hmac = new Uint8Array(
            await crypto.subtle.sign("HMAC", cryptoKey, msg)
        );

        const offset = hmac[hmac.length - 1] & 0xf;

        const binary =
            ((hmac[offset] & 0x7f) << 24) |
            ((hmac[offset + 1] & 0xff) << 16) |
            ((hmac[offset + 2] & 0xff) << 8) |
            (hmac[offset + 3] & 0xff);

        const code = String(binary % 10 ** digits).padStart(digits, "0");
        const timeRemaining = period - (epoch % period);

        return { code, timeRemaining };
    }
};

function base32ToBytes(base32) {
    const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
    const clean = base32.replace(/=+$/, "").replace(/\s+/g, "").toUpperCase();

    let bits = "";

    for (const char of clean) {
        const val = alphabet.indexOf(char);
        if (val === -1) throw new Error("Invalid base32 character");
        bits += val.toString(2).padStart(5, "0");
    }

    const bytes = [];
    for (let i = 0; i + 8 <= bits.length; i += 8) {
        bytes.push(parseInt(bits.slice(i, i + 8), 2));
    }

    return new Uint8Array(bytes);
}

function counterToBytes(counter) {
    const bytes = new Uint8Array(8);

    for (let i = 7; i >= 0; i--) {
        bytes[i] = counter & 0xff;
        counter = Math.floor(counter / 256);
    }

    return bytes;
}





