    if (serials.length > 1) {
        const zip = {};

        for (let i = 0; i < serials.length; i++) {
            ctx.fillStyle = "white";
            ctx.fillRect(0, 0, cnv.width, cnv.height);
            ctx.drawImage(await drawLabel(customer, serials[i]), 0, 0);

