const specials = ["!", "@", "#", "$", "%", "&", "*", "?"];



function randomItem(arr) {
    return arr[Math.floor(Math.random() * arr.length)];
}



function capitalize(word) {
    return word.charAt(0).toUpperCase() + word.slice(1);
}



function shuffle(arr) {
    for (let i = arr.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return arr;
}



function generatePassword() {
    let selectedWords = [
        randomItem(words3),
        randomItem(words4),
        randomItem(words5)
    ];
    const capIndex = Math.floor(Math.random() * selectedWords.length);
    selectedWords[capIndex] = capitalize(selectedWords[capIndex]);
    const symbol = randomItem(specials);
    const digit = Math.floor(Math.random() * 10).toString();
    const firstWordIndex = Math.floor(Math.random() * selectedWords.length);
    const firstWord = selectedWords.splice(firstWordIndex, 1)[0];
    const remainingParts = [
        ...selectedWords,
        symbol,
        digit
    ];
    shuffle(remainingParts);
    return firstWord + remainingParts.join("");
}


